    char *buffer = malloc(total);  // 分配了 0 字节！

    // 但循环仍按 count * item_size 写入
    for (int i = 0; i < count; i++) {
        memcpy(buffer + i * item_size, get_data(), item_size);
        // ← 缓冲区溢出！
    }
}
```

